def gen(rng):
    def fmt(xs):
        return str(len(xs)) + '\n' + '\n'.join(map(str, xs))

    tests = [fmt([0]), fmt([1]), fmt([15]), fmt([16]), fmt([0xABCDE]), fmt([0x1200]), fmt([0xFFFFFFFF]),
             fmt([0x80000000, 0x10000000, 0x00000001, 0x12345678, 0x0F0F0F0F, 0xF0F0F0F0])]
    for _ in range(30):
        k = rng.randint(1, 8)
        tests.append(fmt([rng.randint(0, 16 ** k - 1) for _ in range(rng.randint(1, 10))]))
    for _ in range(10):
        tests.append(fmt([rng.randint(0, 255) * 16 ** rng.randint(0, 6) for _ in range(rng.randint(1, 10))]))
    tests.append(fmt([rng.randint(0, 2 ** 32 - 1) for _ in range(100000)]))
    tests.append(fmt([2 ** 32 - 1 - rng.randint(0, 5) for _ in range(100000)]))
    tests.append(fmt([rng.randint(0, 255) * 16 ** rng.randint(0, 6) for _ in range(100000)]))
    return tests

